\u0057\u0078\u007b\u0044\u0079\u0073\u004f\u0050\u0031\u006e\u006e\u002c\u006f\u0023\u0021\u0039\u007c\u006d\u005c\u0049\u0061\u0036\u005b\u002e\u0072\u0028\u003a\u0039\u003b\u0042\u002a\u005e\u006f\u004a\u005d\u002d\u0050\u0066\u0052\u0039\u0055\u0028\u0045\u0059\u0065\u0032\u0069\u004f\u005b\u0046\u004e\u0072\u0063\u0068\u0024\u002a\u0074\u0059\u0033\u0079\u0068\u0046\u002d\u0061\u0068\u003b\u005f\u0046\u0055\u0021\u006d\u0071\u0024\u0079\u0053\u004d\u004f\u0053\u0072\u0056\u0028\u0033\u006c\u004a\u0059\u0055\u0035\u0024\u003e\u0059\u005a\u0054\u0075\u0040\u0063\u0032\u002e\u0052\u0045\u005e\u0067\u007a\u0058\u0055\u0030\u006c\u0020\u0048\u005a\u003a\u0031\u0071\u0078\u0076\u0020\u0050\u0039\u0063\u0053\u0027\u007e\u0020\u0045\u0047\u0079\u0074\u003c\u0026\u0056\u004a\u005b\u004b\u0064\u003f\u004f\u003a\u0046\u0055\u0052\u0041\u002c\u007e\u006d\u0052\u004a\u006d\u0051\u0036\u004c\u0067\u0023\u003a\u002b\u0041\u002b\u0032\u0075\u0052\u0072\u003e\u002f\u0045\u0029\u006f\u0066\u002b\u0048\u0061\u007c\u0062\u007a\u004b\u0067\u0046\u003e\u0040\u0033\u006c\u0074\u0050\u0044\u0032\u0033\u004a\u002d\u0056\u0041\u0045\u006c\u0032\u004c\u0029\u0026\u004f\u004d\u005c\u0020\u0068\u0025\u005a\u0027\u006d\u004d\u004a\u0060\u0043\u0078\u0055\u0020\u004c\u005d\u0032\u0061\u0076\u0048\u004e\u002d\u0053\u0028\u0047\u0032\u0063\u0074\u0046\u0050\u0044\u007a\u0031\u0035\u0032\u0062\u0039\u0030\u0067\u002a\u005d\u0065\u0044\u006b\u0031\u006a\u004f\u0068\u0043\u0042\u0048\u0070\u004f\u003f\u0043\u007d\u0029\u0036\u0055\u007c\u002f\u002e\u0062\u0050\u003a\u0067\u0067\u0027\u006c\u007c\u003a\u0038\u0053\u0023\u0048\u0055\u0035\u002e\u003d\u003b\u004b\u002f\u0033\u0034\u0032\u0064\u004a\u0051\u005c\u0022\u0060\u0056\u0045\u004a\u0044\u006c\u0076\u0064\u0031\u0046\u0060\u0031\u0061\u0074\u006b\u005a\u0027\u005c\u005d\u0075\u003b\u0042\u0042\u0045\u0064\u002b\u0059\u0042\u003d\u003e\u0057\u004d\u0031\u006a\u002c\u005f\u002f\u006f\u002b\u0060\u0065\u0050\u0041\u005a\u002b\u0071\u0020\u0036\u0051\u006b\u004f\u0068\u004e\u006f\u003e\u0029\u004d\u0066\u0036\u0075\u0025\u0029\u007c\u0039\u0039\u0068\u002a\u002f\u0020\u0028\u0067\u0051\u004a\u0027\u0028\u002c\u0072\u007b\u0026\u0060\u0021\u0044\u0020\u0038\u002f\u002d\u007c\u007e\u0040\u0056\u005f\u0068\u0061\u0049\u003d\u005d\u0057\u0072\u007a\u0020\u004c\u0044\u0061\u0078\u006f\u0029\u0064\u0072\u007d\u0058\u006a\u0067\u004e\u003c\u0061\u0045\u005c\u0065\u0040\u0029\u0043\u007e\u005e\u0068\u0054\u002d\u005f\u0021\u0064\u0065\u007a\u0070\u002a\u0049\u0044\u0030\u0038\u0062\u0057\u005f\u0066\u006e\u0027\u0035\u005a\u003e\u004a\u0063\u0026\u0078\u0038\u0044\u005f\u007a\u006e\u0059\u0028\u004d\u006e\u0079\u0064\u0020\u003b\u0058\u003d\u004d\u0043\u0076\u002c\u0077\u005f\u007b\u002c\u002b\u0035\u0043\u0066\u0059\u0031\u0043\u003b\u0052\u003d\u0032\u005f\u0079\u006f\u004a\u0024\u002f\u0030\u002b\u006a\u0072\u0027\u0060\u007a\u0035\u0068\u0033\u0037\u0040\u0072\u002e\u0041\u002e\u0033\u0054\u0073\u0046\u003b\u0077\u0034\u0078\u006c\u0070\u006a\u005d\u0021\u005a\u0020\u006c\u0074\u0070\u0064\u0053\u0024\u005a\u0048\u005e\u0072\u0068\u0050\u0020\u002e\u0059\u0021\u0042\u0038\u0056\u0039\u0026\u006c\u0049\u0062\u003f\u0026\u002e\u0046\u0036\u0047\u005e\u0049\u0027\u002d\u0038\u0063\u0038\u0054\u0063\u0045\u0039\u0073\u0073\u002c\u002e\u004e\u0065\u0054\u0064\u0045\u002f\u0040\u003e\u006e\u005b\u0031\u0077\u006d\u003b\u003e\u0038\u007b\u0052\u006a\u0062\u0067\u005a\u0067\u002a\u0044\u0072\u004f\u0064\u0050\u0033\u005b\u0079\u005d\u003b\u0037\u0027\u0076\u007d\u0040\u0074\u0071\u0067\u0067\u0053\u004c\u006e\u004f\u003c\u003c\u005a\u005b\u0024\u0063\u0062\u005c\u003d\u007c\u0063\u0058\u007b\u0052\u006d\u0064\u006d\u004f\u0071\u0058\u0054\u004c\u005b\u0063\u0021\u0063\u0065\u0058\u005b\u004d\u0031\u0022\u004c\u0037\u002d\u0069\u0041\u0053\u004b\u0051\u0020\u007e\u0054\u0041\u0073\u0076\u007b\u006c\u0023\u0074\u007c\u002d\u005f\u0040\u006d\u003c\u003b\u0044\u006b\u0057\u005f\u005a\u0072\u0033\u0050\u0047\u002f\u0071\u0036\u006f\u0031\u0068\u0030\u005b\u0053\u0051\u005b\u0042\u002d\u006d\u0061\u003d\u0058\u005d\u006c\u005a\u006a\u0068\u003b\u003b\u003c\u0029\u0055\u004b\u0045\u0066\u0057\u0039\u005d\u0079\u0060\u006d\u0025\u003c\u0076\u003d\u006e\u0055\u007d\u006a\u0057\u0050\u0070\u0050\u0052\u0069\u0047\u0076\u002a\u0021\u006c\u007e\u004f\u0046\u0036\u002b\u0059\u002e\u002b\u0049\u0072\u002a\u0056\u004e\u005f\u0071\u0039\u0031\u0024\u0079\u002e\u0052\u0033\u0067\u0031\u0039\u0068\u004f\u0042\u003b\u0022\u0073\u006a\u0041\u005a\u0025\u002c\u0041\u007c\u0054\u005f\u0062\u0028\u0050\u006b\u0049\u0057\u002c\u006f\u0038\u0063\u0067\u002e\u005c\u006f\u0033\u007a\u0022\u0066\u0051\u0048\u0072\u0079\u0053\u004e\u0033\u0037\u006a\u0066\u0053\u0077\u003c\u005d\u0040\u007e\u0045\u0032\u0070\u0020\u0021\u006c\u0066\u0033\u0046\u0021\u0023\u0063\u0055\u0078\u006c\u006d\u0066\u0031\u002a\u0077\u002e\u0042\u0032\u0029\u002d\u007a\u003a\u0044\u0078\u0025\u0030\u0055\u005b\u0027\u0051\u0041\u002a\u005b\u0031\u007a\u002a\u0076\u0064\u0040\u0049\u0068\u004a\u004d\u0062\u0044\u005a\u003c\u0077\u0046\u0070\u0047\u0029\u0076\u003b\u005b\u003d\u0047\u0077\u0033\u004c\u002d\u0078\u0023\u003b\u0064\u006d\u004d\u003b\u0032\u0056\u0027\u0060\u0049\u0061\u002c\u0047\u003b\u006b\u0061\u0028\u003b\u003a\u0021\u0073\u0051\u0030\u0045\u005a\u007d\u0070\u0066\u0065\u0029\u0061\u0048\u0053\u004d\u004b\u006e\u002e\u0070\u0045\u0049\u0062\u003d\u0059\u0058\u0055\u0038\u0061\u0021\u005c\u0075\u0070\u0042\u0079\u0048\u0079\u0056\u006b\u002a\u0039\u004d\u0067\u005a\u0030\u0032\u006c\u0075\u0029\u0070\u0042\u0039\u0059\u003c\u0032\u005f\u006f\u0075\u006d\u004a\u0066\u006b\u0041\u006b\u003f\u0061\u0063\u0039\u003f\u0054\u002a\u0070\u006c\u0045\u0033\u006b\u0023\u005d\u0045\u0060\u004c\u0067\u005f\u0058\u002e\u0032\u0023\u0053\u0059\u0060\u005b\u0027\u006d\u0040\u006e\u005c\u0027\u0042\u0050\u0056\u0021\u0057\u004b\u006d\u003e\u003b\u0060\u0046\u0022\u0045\u002b\u0048\u0034\u006b\u0034\u0021\u0067\u0062\u007a\u0053\u004c\u002c\u004e\u0073\u002f\u0025\u0044\u0057\u0076\u0026\u004f\u0035\u0072\u003f\u007b\u003c\u0045\u0031\u0040\u0046\u003d\u0036\u0052\u006c\u0077\u007e\u002b\u004b\u003d\u0051\u0027\u002c\u006f\u0051\u0044\u0040\u0032\u0036\u0066\u0050\u0044\u003f\u0064\u002e\u006b\u0032\u0028\u0036\u004e\u005c\u0037\u0075\u0036\u0042\u0068\u0046\u0043\u0033\u004e\u0064\u007d\u0046\u003d\u003d\u004a\u0065\u0022\u005e\u004d\u0042\u0031\u003f\u0024\u007a\u0027\u0025\u003a\u006c\u006f\u006d\u0024\u004e\u0040\u0024\u005c\u0048\u0049\u0078\u002a\u002f\u0039\u005d\u0035\u0060\u005c\u0068\u0056\u0031\u007d\u007d\u006b\u003e\u002d\u0043\u0026\u0050\u0069\u004f\u002f\u0070\u0068\u0020\u0028\u0044\u0029\u003f\u004d\u0020\u0047\u0077\u0054\u004d\u005e\u0053\u0052\u006d\u003a\u0024\u004d\u004b\u0020\u0074\u005f\u004c\u0074\u0044\u0031\u0041\u0050\u0030\u0032\u003f\u004c\u0070\u003b\u0066\u0067\u0071\u0042\u0059\u006e\u0036\u0074\u0055\u004f\u004b\u003e\u003a\u0051\u0042\u003f\u0067\u0075\u007a\u0069\u002a\u003d\u002e\u0056\u003c\u002b\u002e\u0049\u006f\u0048\u0063\u0021\u0073\u0069\u0031\u002a\u0044\u0063\u002e\u0020\u007d\u006b\u0028\u003e\u0025\u0053\u0040\u0045\u004d\u005b\u002b\u0031\u002b\u0059\u0050\u0047\u0074\u003e\u0062\u005f\u0030\u0053\u0068\u0031\u0063\u003f\u0078\u0023\u002f\u0023\u0069\u0021\u0054\u007d\u0057\u0077\u0056\u0045\u0077\u0072\u0031\u0022\u0068\u0074\u002b\u0044\u0028\u0031\u005f\u0033\u003e\u0036\u0030\u0076\u0061\u0067\u002b\u0055\u0074\u0075\u0044\u0042\u005d\u005c\u0034\u0021\u0027\u0024\u005a\u003c\u0073\u0043\u0079\u0028\u007d\u007d\u0067\u0059\u004d\u007a\u003b\u006a\u005e\u004d\u004a\u0056\u0028\u0045\u0047\u005c\u007e\u007a\u0021\u0070\u005e\u0027\u004a\u0076\u0020\u005b\u0027\u006f\u004e\u0055\u0066\u006e\u0038\u0032\u006c\u0074\u0039\u002b\u0030\u0072\u003b\u005c\u003f\u006a\u0051\u006d\u0049\u0023\u0052\u007b\u003d\u004f\u0076\u0046\u002c\u0076\u003b\u005b\u004f\u0032\u004a\u003d\u0025\u004a\u003b\u002e\u003f\u0033\u0026\u0026\u0028\u007e\u007d\u0079\u007a\u0057\u0034\u0021\u0027\u0049\u0060\u0064\u003d\u0024\u0071\u0028\u0035\u005a\u004c\u0070\u003e\u0030\u0034\u0070\u0043\u004c\u0034\u003e\u0029\u0021\u006e\u0059\u0056\u003a\u004a\u006c\u002a\u004a\u0045\u0048\u0033\u0079\u0052\u0073\u005d\u007d\u006a\u0034\u0038\u0062\u005d\u005d\u0052\u007b\u006f\u0029\u005b\u0024\u0039\u0021\u0033\u0060\u005c\u0053\u0070\u0049\u004c\u0025\u0061\u0055\u003b\u0038\u0032\u0054\u0039\u002b\u006f\u0020\u0052\u003d\u0054\u0041\u005b\u0075\u007a\u0068\u0038\u004a\u006b\u002a\u0032\u005e\u0030\u0068\u0032\u005d\u0028\u0047\u0057\u0032\u0036\u007d\u0037\u0026\u003a\u0058\u007e\u0041\u005b\u003b\u0064\u0038\u007c\u006e\u0054\u003b\u006e\u004a\u004d\u0031\u003c\u0037\u0072\u0028\u002e\u0048\u003f\u007b\u0070\u0051\u003e\u0042\u007c\u005e\u0028\u0072\u002e\u0041\u0033\u0020\u006c\u003c\u0071\u007c\u0041\u0027\u005a\u0049\u0035\u0057\u0041\u005f\u007d\u0057\u004a\u003f\u003b\u0064\u0060\u0034\u0042\u003f\u003f\u0027\u005f\u0037\u007b\u006c\u0044\u0045\u004d\u0039\u007e\u0060\u003c\u005d\u0057\u0060\u0070\u0033\u0033\u006b\u0064\u0024\u005b\u0036\u0062\u004e\u004b\u0043\u0042\u0066\u0042\u0078\u0057\u0077\u007b\u005d\u0048\u0050\u0042\u0068\u0058\u007e\u0047\u0024\u005a\u0068\u0036\u0049\u004d\u0029\u0079\u003a\u005a\u0077\u004c\u0027\u0063\u0034\u0069\u005b\u003d\u0064\u0039\u0072\u0029\u006a\u0055\u002e\u0072\u0076\u0067\u0055\u0037\u0023\u005e\u005e\u003c\u0077\u003e\u003a\u006f\u0038\u0026\u004b\u0050\u005c\u0068\u0061\u006f\u0052\u006a\u004a\u0062\u0074\u006c\u0066\u0075\u005a\u003f\u0027\u0070\u004f\u005a\u0022\u0036\u0062\u007a\u0073\u0038\u0049\u0064\u007e\u0076\u002d\u0056\u0039\u006d\u004a\u0051\u002c\u006a\u004a\u007c\u004d\u0047\u0032\u0065\u0048\u0039\u007d\u0034\u0044\u0030\u004c\u0066\u006d\u0078\u006e\u005d\u0049\u002e\u004a\u005a\u007c\u0074\u0052\u0073\u0043\u002e\u0059\u0045\u0066\u0049\u0072\u0060\u006e\u002d\u003b\u0047\u005e\u002a\u005d\u0029\u002d\u0059\u003a\u0052\u0076\u0054\u0054\u0062\u0028\u0075\u0070\u0023\u0044\u0068\u004e\u0045\u0042\u0068\u0032\u0070\u0042\u0072\u0024\u006b\u0072\u0063\u0075\u002d\u0055\u0048\u0053\u0030\u007e\u0030\u002f\u0069\u005a\u0062\u007b\u0030\u006a\u0059\u0053\u0040\u0079\u0049\u0067\u0032\u0070\u0040\u0025\u0023\u002b\u0068\u007e\u0042\u006e\u0033\u0053\u0045\u0044\u0055\u005b\u0022\u006b\u0071\u0051\u0072\u006b\u0065\u0063\u0068\u006f\u0027\u0048\u0079\u0047\u0064\u0028\u0044\u0053\u003c\u004c\u0057\u0057\u0063\u0066\u0062\u0037\u0075\u006f\u006c\u002c\u0051\u0040\u0020\u002f\u005a\u0037\u0065\u003a\u0051\u007c\u0077\u0035\u0060\u0051\u006b\u0050\u006c\u002d\u007a\u0046\u0079\u0079\u005e\u0063\u0063\u0037\u006e\u0020\u007e\u0021\u003e\u006f\u0022\u0056\u0047\u004d\u0033\u0024\u0043\u007e\u0034\u0051\u0041\u003c\u0051\u003c\u0075\u0032\u0040\u003e\u005d\u0078\u0039\u002e\u0045\u0070\u006f\u002c\u0055\u004d\u0050\u002c\u0064\u0058\u003b\u0059\u0038\u003d\u0074\u0023\u0066\u005b\u0068\u0058\u0047\u0043\u0027\u0058\u005e\u005f\u0057\u0065\u0049\u0076\u002c\u0029\u0062\u004d\u005b\u0071\u006b\u0058\u007d\u0038\u0058\u0045\u002b\u0038\u002c\u0027\u0022\u0062\u005f\u004f\u006e\u0054\u006d\u0053\u0056\u002f\u0031\u002d\u005c\u0054\u0048\u0074\u0034\u0031\u0069\u007a\u002e\u0072\u0079\u0034\u003c\u002d\u0073\u002d\u0063\u0029\u002d\u005e\u0055\u007b\u0034\u002c\u003a\u0078\u0038\u0047\u0074\u0074\u0056\u0027\u004c\u0072\u005e\u0028\u0022\u007d\u0064\u0045\u0030\u0054\u0030\u006c\u0025\u006d\u0021\u002b\u0034\u0028\u0029\u0061\u0030\u0050\u0057\u0027\u0068\u0077\u003a\u005d\u005e\u0058\u002f\u004a\u0077\u007a\u004d\u006c\u002f\u003b\u003f\u007c\u0054\u0048\u007a\u0040\u0077\u0055\u0024\u0070\u003b\u0038\u002d\u004f\u003f\u005e\u0050\u003b\u0024\u0049\u0073\u0040\u005b\u0021\u0029\u006b\u0065\u0069\u005e\u0024\u0023\u0061\u0047\u007b\u0050\u0022\u004c\u004a\u004a\u002b\u002f\u0032\u005c\u0079\u0058\u0054\u003a\u0036\u006e\u0034\u005b\u002d\u0053\u0074\u003f\u007a\u0068\u0075\u0077\u0052\u0066\u0038\u0029\u0039\u0075\u0071\u0022\u0038\u0057\u003a\u0035\u003b